package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type PartRec struct { // 01 PART-REC, 15 bytes
	LbPart   string // PIC X(8) @0 len=8
	LbRegion string // PIC X(3) @8 len=3
	LbSerial int64  // PIC 9(4) @11 len=4
}

// Standalone working-storage items
var WsEofFlag string
var WsLabel string
var WsACount int64
var WsTotalA int64
var WsCount int64

var curRec PartRec
var partLines []string
var partIdx int

func init() {
	WsEofFlag = "N"
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0
	WsTotalA = 0
	WsCount = 0
}

func inputDone() bool {
	return WsEofFlag == "Y"
}

func openPartFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			partLines = nil
			partIdx = 0
			return
		}
		fmt.Fprintln(os.Stderr, err.Error())
		os.Exit(1)
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	scanner.Buffer(make([]byte, 64*1024), 1024*1024)
	partLines = nil
	for scanner.Scan() {
		partLines = append(partLines, scanner.Text())
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		os.Exit(1)
	}
	partIdx = 0
}

func closePartFile() {
}

func parseSerial(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	n, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		return 0
	}
	if n < 0 {
		return 0
	}
	return n % 10000
}

func delimitedBySpace(s string) string {
	if i := strings.IndexByte(s, ' '); i >= 0 {
		return s[:i]
	}
	return s
}

func MainPara() {
	openPartFile()
	ReadPara()
	for !inputDone() {
		ProcessPara()
	}
	closePartFile()
	SummaryPara()
}

func ReadPara() {
	if partIdx >= len(partLines) {
		WsEofFlag = "Y"
		return
	}
	line := partLines[partIdx]
	partIdx++
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	curRec.LbPart = line[0:8]
	curRec.LbRegion = line[8:11]
	curRec.LbSerial = parseSerial(line[11:15])
}

func ProcessPara() {
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0
	var cnt int64
	for i := 0; i < len(curRec.LbPart); i++ {
		if curRec.LbPart[i] == 'A' {
			cnt++
		}
	}
	WsACount = cnt % 100
	regionPart := delimitedBySpace(curRec.LbRegion)
	partPart := delimitedBySpace(curRec.LbPart)
	serialPart := fmt.Sprintf("%04d", curRec.LbSerial%10000)
	buf := make([]byte, 20)
	for i := range buf {
		buf[i] = ' '
	}
	pos := 0
	sources := []string{regionPart, "-", partPart, "-", serialPart}
	for _, src := range sources {
		for i := 0; i < len(src) && pos < 20; i++ {
			buf[pos] = src[i]
			pos++
		}
	}
	WsLabel = string(buf)
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")
	WsTotalA = (WsTotalA + WsACount) % 1000
	WsCount = (WsCount + 1) % 1000
	cntStr := fmt.Sprintf("%02d", WsACount%100)
	out := WsLabel + " A=" + cntStr + "\n"
	if _, err := os.Stdout.WriteString(out); err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		os.Exit(1)
	}
	ReadPara()
}

func SummaryPara() {
	out := "LABELS: " + fmt.Sprintf("%03d", WsCount%1000) + " A-TOTAL: " + fmt.Sprintf("%03d", WsTotalA%1000) + "\n"
	if _, err := os.Stdout.WriteString(out); err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		os.Exit(1)
	}
}

func main() {
	MainPara()
}
